        }
      } catch {
        // RTM native module not linked (web/simulator) — silent degrade
      }
    };

    void init();

    return () => {
      mounted = false;
      const client = rtmClientRef.current as { logout?: () => Promise<void> } | null;
      if (client?.logout) void client.logout().catch(() => {});
      rtmClientRef.current = null;
      setReady(false);
